contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // call withdrawAll as caller 'caller' sending at least 'funds' in this contract beforehand
    function run(address caller, address recipient, uint256 funds) public {
        // ensure this contract has enough ETH to fund C
        require(address(this).balance >= funds);

        // fund C so it has balance to withdraw
        payable(address(c)).transfer(funds);

        // capture balance before
        uint256 before = address(c).balance;

        // require that msg.sender is not the owner to trigger the distinguishing condition
        // we can't read owner directly inside require (allowed), so fetch owner
        address owner = c.owner();
        require(caller != owner);

        // perform the call as 'caller' by using low-level call with value 0 and setting msg.sender via calldata sender spoofing
        // Solidity does not let us change msg.sender; instead we simulate by requiring that the test caller (this transaction sender)
        // is the provided 'caller' and then call withdrawAll. To ensure the msg.sender != owner condition holds for c,
        // we require tx.origin == caller so that the test is invoked by that account.
        require(tx.origin == caller);

        // calling withdrawAll: this will have msg.sender == caller (tx.origin) which per above is != owner
        c.withdrawAll(recipient);

        uint256 after = address(c).balance;

        // In original contract, withdrawAll only allows msg.sender==owner, so a non-owner caller cannot transfer funds;
        // thus the balance must remain the same. The mutant allows recipient==owner which could let non-owner call succeed
        // when recipient==owner; therefore we assert balance unchanged to be violated by the mutant.
        assert(after == before);
    }

    // allow this contract to receive ETH for funding tests
    receive() external payable {}
}

