    function run(address caller, address recipient) public payable {
        // Precondition: ensure the call is made from `caller` by using low-level call from this contract.
        // We implement this by requiring caller == address(this) or using a revert if not — but since we cannot change msg.sender,
        // we instead require nothing special and perform the call via a delegate pattern: use an internal call from address(this).
        // To simulate a call from `caller`, we will only allow caller == address(this) (so the test caller is this contract).
        require(caller == address(this));

        bool reverted;
        // call withdrawAll from this contract (so msg.sender == address(this))
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }

        // General rule: if this contract is not the owner, withdrawAll must revert.
        // We can observe owner via c.owner() public getter.
        address owner = c.owner();
        assert((address(this) == owner) || reverted);
    }
    receive() external payable { }
