import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz the caller and the recipient addresses
    function testFuzz_property(address caller, address recipient) public {
        // keep addresses non-zero to be in an admissible domain
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));
        // fund the contract with some ETH from an arbitrary funder
        address funder = address(0xBEEF);
        vm.deal(funder, 1 ether);
        vm.prank(funder);
        (bool s,) = address(c).call{value: 1 ether}("");
        require(s);

        // Now have `caller` invoke withdrawAll(recipient).
        // If caller is owner (address(this)), withdraw should succeed and drain balance.
        // If caller is not owner, in the correct contract it must NOT allow draining (call will revert),
        // whereas the mutant allowing recipient==owner would let a non-owner caller drain when recipient==owner.
        bool ok;
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: only an owner-originated call can succeed in draining the contract.
        // Thus: (caller == owner)  iff  call succeeded and contract balance is zero.
        // We observe via address(c).balance. This single assertion is true for the reference
        // for all inputs, and the mutant (which allows recipient==owner) will make it false
        // for some inputs (caller != owner but recipient == owner and call succeeds).
        bool drained = address(c).balance == 0;
        assertTrue((caller == address(this)) == (ok && drained));
    }
}

