pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: caller (actor) and recipient; the fuzzer will search addresses to find a counterexample
    function testFuzz_property(address caller, address recipient) public {
        // keep domain wide but avoid trivially equal/corner cases that are not useful
        // allow caller to be any address but ensure it's not the owner (address(this)) to test non-owner behavior
        vm.assume(caller != address(this));
        // ensure recipient can be any address (including owner) — do not exclude recipient==owner

        // fund the contract with some ETH so withdrawAll would have something to transfer if allowed
        uint256 fund = 1 ether;
        vm.deal(address(this), fund);
        // send funds to the contract
        (bool sent,) = address(c).call{value: fund}("\x00");
        require(sent, "funding failed");

        // record balance before
        uint256 before = address(c).balance;
        // sanity: before must be >0
        vm.assume(before > 0);

        // have the fuzzed caller invoke withdrawAll(recipient)
        vm.prank(caller);
        bool ok;
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the reference contract guarantees that if the caller is NOT the owner,
        // the contract balance remains unchanged (only the owner may successfully cause the contract
        // to transfer out its balance). The mutant that allows recipient==owner lets a non-owner
        // trigger a transfer to the owner when they pass owner as recipient, violating this.
        // We assert that for the given (caller != owner) case, the contract balance is still the same.
        if (caller != address(this)) {
            assertTrue(address(c).balance == before);
        } else {
            // If caller == owner (shouldn't happen due to assume), still assert the invariant trivially
            assertTrue(address(c).balance <= before);
        }
    }
}
